CREATE TABLE IF NOT EXISTS users (id BIGINT PRIMARY KEY AUTO_INCREMENT, username VARCHAR(40) NOT NULL UNIQUE, email VARCHAR(190) NOT NULL UNIQUE, password_hash VARCHAR(100) NOT NULL, role VARCHAR(16) NOT NULL DEFAULT 'USER', created_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE IF NOT EXISTS auth_tokens (token_hash CHAR(64) PRIMARY KEY, user_id BIGINT NOT NULL, expires_at BIGINT NOT NULL, FOREIGN KEY (user_id) REFERENCES users(id) ON DELETE CASCADE);
CREATE TABLE IF NOT EXISTS categories (id BIGINT PRIMARY KEY AUTO_INCREMENT, name VARCHAR(60) NOT NULL UNIQUE, icon VARCHAR(30) NOT NULL DEFAULT 'grid');
CREATE TABLE IF NOT EXISTS skill_groups (id BIGINT PRIMARY KEY AUTO_INCREMENT, category_id BIGINT NOT NULL, name VARCHAR(60) NOT NULL, description VARCHAR(300), UNIQUE KEY uk_group (category_id, name), FOREIGN KEY (category_id) REFERENCES categories(id));
CREATE TABLE IF NOT EXISTS skills (id BIGINT PRIMARY KEY AUTO_INCREMENT, name VARCHAR(100) NOT NULL, normalized_name VARCHAR(100) NOT NULL, description TEXT, group_id BIGINT NOT NULL, creator_id BIGINT NULL, source_type VARCHAR(16) NOT NULL, status VARCHAR(16) NOT NULL, difficulty TINYINT NOT NULL DEFAULT 2, created_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP, INDEX idx_skill_name (normalized_name), FOREIGN KEY (group_id) REFERENCES skill_groups(id), FOREIGN KEY (creator_id) REFERENCES users(id) ON DELETE SET NULL);
CREATE TABLE IF NOT EXISTS skill_aliases (id BIGINT PRIMARY KEY AUTO_INCREMENT, skill_id BIGINT NOT NULL, alias VARCHAR(100) NOT NULL, normalized_alias VARCHAR(100) NOT NULL, UNIQUE KEY uk_skill_alias (skill_id, normalized_alias), FOREIGN KEY (skill_id) REFERENCES skills(id) ON DELETE CASCADE);
CREATE TABLE IF NOT EXISTS skill_reviews (skill_id BIGINT PRIMARY KEY, reason VARCHAR(300) NOT NULL, reviewed_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP, FOREIGN KEY (skill_id) REFERENCES skills(id) ON DELETE CASCADE);
CREATE TABLE IF NOT EXISTS user_skills (id BIGINT PRIMARY KEY AUTO_INCREMENT, user_id BIGINT NOT NULL, skill_id BIGINT NOT NULL, level TINYINT NOT NULL DEFAULT 1, status VARCHAR(20) NOT NULL DEFAULT 'WANT_TO_LEARN', note VARCHAR(1000), updated_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP, UNIQUE KEY uk_user_skill (user_id, skill_id), FOREIGN KEY (user_id) REFERENCES users(id) ON DELETE CASCADE, FOREIGN KEY (skill_id) REFERENCES skills(id) ON DELETE CASCADE);
CREATE TABLE IF NOT EXISTS trees (id BIGINT PRIMARY KEY AUTO_INCREMENT, user_id BIGINT NOT NULL, name VARCHAR(100) NOT NULL, description VARCHAR(500), visibility VARCHAR(16) NOT NULL DEFAULT 'PRIVATE', created_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP, FOREIGN KEY (user_id) REFERENCES users(id) ON DELETE CASCADE);
CREATE TABLE IF NOT EXISTS tree_nodes (id BIGINT PRIMARY KEY AUTO_INCREMENT, tree_id BIGINT NOT NULL, skill_id BIGINT NOT NULL, x DOUBLE NOT NULL, y DOUBLE NOT NULL, custom_label VARCHAR(100), UNIQUE KEY uk_tree_skill (tree_id, skill_id), FOREIGN KEY (tree_id) REFERENCES trees(id) ON DELETE CASCADE, FOREIGN KEY (skill_id) REFERENCES skills(id));
CREATE TABLE IF NOT EXISTS tree_edges (id BIGINT PRIMARY KEY AUTO_INCREMENT, tree_id BIGINT NOT NULL, source_node_id BIGINT NOT NULL, target_node_id BIGINT NOT NULL, UNIQUE KEY uk_tree_edge (tree_id, source_node_id, target_node_id), FOREIGN KEY (tree_id) REFERENCES trees(id) ON DELETE CASCADE, FOREIGN KEY (source_node_id) REFERENCES tree_nodes(id) ON DELETE CASCADE, FOREIGN KEY (target_node_id) REFERENCES tree_nodes(id) ON DELETE CASCADE);
